def choose_move(observation):
    # Defensive defaults
    x = observation.get("agent_x", 0)
    y = observation.get("agent_y", 0)

    # Helper: safe delta in [-1,0,1]
    def clamp_delta(dx, dy):
        if dx not in (-1, 0, 1) or dy not in (-1, 0, 1):
            return 0, 0
        return dx, dy

    # Simple robust heuristic across tasks:
    # If there are visible resources, move toward the closest resource.
    # Else if there is an opponent to pursue, move toward them.
    # Else if in territory, try to center away from edges (biased to stay safe).
    # Else random-looking but deterministic from observation keys.
    resources = observation.get("resources", [])
    enemies = observation.get("enemies", [])
    territory = observation.get("territory", {})

    def dist(a, b):
        ax, ay = a
        bx, by = b
        return abs(ax - bx) + abs(ay - by)

    # Pick closest resource
    if resources:
        closest = min(resources, key=lambda p: dist((x, y), (p[0], p[1])))
        rx, ry = closest[0], closest[1]
        dx = 0 if rx == x else (1 if rx > x else -1)
        dy = 0 if ry == y else (1 if ry > y else -1)
        return clamp_delta(dx, dy)

    # Pursue closest enemy if any
    if enemies:
        closest = min(enemies, key=lambda p: dist((x, y), (p[0], p[1])))
        ex, ey = closest[0], closest[1]
        dx = 0 if ex == x else (1 if ex > x else -1)
        dy = 0 if ey == y else (1 if ey > y else -1)
        return clamp_delta(dx, dy)

    # Territory-centric: try to stay away from edges if territory info available
    if territory:
        w = territory.get("width", 1)
        h = territory.get("height", 1)
        margin = 1
        # Move away from nearest edge
        dx = 0
        dy = 0
        if x <= margin:
            dx = 1
        elif x >= w - margin - 1:
            dx = -1
        if y <= margin:
            dy = 1
        elif y >= h - margin - 1:
            dy = -1
        if dx != 0 or dy != 0:
            return clamp_delta(dx, dy)

    # Fallback: deterministic neutral move based on position parity
    # Try to move diagonally-like toward center of map if known; otherwise stay
    if "center" in observation:
        cx, cy = observation["center"]
        dx = 0 if cx == x else (1 if cx > x else -1)
        dy = 0 if cy == y else (1 if cy > y else -1)
        return clamp_delta(dx, dy)

    # Last resort: small deterministic pattern
    pattern = (x + y) % 3
    if pattern == 0:
        return (0, 0)
    if pattern == 1:
        return (1, 0)
    return (0, 1)

